"""Public Privacy Policy and Terms pages (no sign-in), reached with ?page=privacy or ?page=terms."""
import streamlit as st

PRIVACY = '# Privacy Policy\nRx Transfer, operated by Payson Apothecary Pharmacy, LLC\n904 E Wagon Wheel Circle, Payson, AZ 85541\nEffective: November 18, 2026\n\nPayson Apothecary Pharmacy, LLC ("Payson Apothecary", "we") runs Rx Transfer, a web app that lets approved pharmacy staff send prescription-transfer fax requests.\n\nWhat we collect: your name, email address, mobile phone number, and professional license details you give us when you sign up, so that we can approve your account and sign you in. We also collect the pharmacy and fax details you enter so the app can send your fax requests.\n\nHow we use it: to verify and approve users, send one-time sign-in codes by text message or email, send the fax requests you ask us to send, and support the app. We do not use your information for marketing.\n\nText messages: Your mobile number is used only to send sign-in codes you request. We do not sell, rent, or share your mobile number or SMS opt-in consent with third parties or affiliates for marketing or promotional purposes. Text messaging originator opt-in data and consent will not be shared with any third parties, except service providers (such as our SMS carrier) that deliver the messages for us.\n\nWho we share with: only the service providers needed to run the app (for example, our sign-in, text messaging, fax, and hosting providers), and only as needed to provide the service, or when required by law. We do not sell personal information.\n\nRetention: we keep account information while your account is active and delete it on request. Fax requests are kept only as long as needed to complete them.\n\nYour choices: reply STOP to any text to stop messages. To update or delete your account, email craig.paysonapothecary@hotmail.com.\n\nContact: Payson Apothecary Pharmacy, LLC, 904 E Wagon Wheel Circle, Payson, AZ 85541, craig.paysonapothecary@hotmail.com.\n'

TERMS = '# Terms and Conditions\nRx Transfer, operated by Payson Apothecary Pharmacy, LLC\n904 E Wagon Wheel Circle, Payson, AZ 85541\nEffective: November 18, 2026\n\nRx Transfer is for licensed pharmacists, pharmacy technicians, and pharmacies approved by Payson Apothecary Pharmacy, LLC. By using it you agree to use it only for legitimate pharmacy business and to follow applicable laws.\n\n## SMS Terms (Rx Transfer Login Codes)\n- Program: Rx Transfer Login Codes sends one-time sign-in codes to approved users who request them on the sign-in page.\n- How you opt in: you type your own mobile number on the sign-in page and tap "Text me a code."\n- Frequency: message frequency varies; you get one text each time you request a code.\n- Cost: Message and data rates may apply.\n- Opt out: reply STOP at any time to stop messages. You\'ll get one confirmation text and no more messages.\n- Help: reply HELP, or email craig.paysonapothecary@hotmail.com.\n- Carriers are not liable for delayed or undelivered messages.\n- Your privacy: see our Privacy Policy. We do not sell or share your mobile number for marketing.\n\n## Other terms\nThe app is provided as-is. We may suspend accounts that misuse it. We may update these terms and will post the new version here.\n\nContact: Payson Apothecary Pharmacy, LLC, 904 E Wagon Wheel Circle, Payson, AZ 85541, craig.paysonapothecary@hotmail.com.\n'


def render_legal_page() -> None:
    """If the URL asks for a legal page, show it and stop the script before sign-in."""
    page = str(st.query_params.get("page", "")).lower()
    if page in ("privacy", "privacy-policy"):
        st.markdown(PRIVACY)
        st.stop()
    if page in ("terms", "sms-terms", "terms-and-conditions"):
        st.markdown(TERMS)
        st.stop()
